tool_input.command:
mkdir -p "$TMPDIR/scratch" && cat > "$TMPDIR/scratch/T.java" <<'EOF'
import java.lang.reflect.Field;
public class T {
    public static final int X = 5;
    public static void main(String[] a) throws Exception {
        Field f = T.class.getDeclaredField("X");
        try {
            Field mf = Field.class.getDeclaredField("modifiers");
            mf.setAccessible(true);
            mf.setInt(f, f.getModifiers() & ~java.lang.reflect.Modifier.FINAL);
            System.out.println("worked, modifiers now: " + f.getModifiers());
        } catch (Throwable t) {
            System.out.println("threw: " + t);
        }
    }
}
EOF
javac -d "$TMPDIR/scratch" "$TMPDIR/scratch/T.java" && java -cp "$TMPDIR/scratch" T
